#!/usr/bin/env python3
"""Write ae9/sources/<ID>.md (one per source) from metadata below plus the raw text region of each excerpt.
Run from anywhere: python3 ae9/tools/write_sources.py"""
import json, re
from pathlib import Path
HERE = Path(__file__).resolve().parent.parent
RAW = HERE / "sources" / "raw"
ns = {}; exec((HERE / "stimuli.py").read_text(encoding="utf-8"), ns)
STIM, RAWMAP = ns["STIM"], ns["RAWMAP"]
data = json.loads((HERE.parent / "euro-exam" / "data" / "unit9.json").read_text(encoding="utf-8"))
items = data["practice"] + data["exam"]["questions"]

OPL = "UK Parliament Hansard, reused under the Open Parliament Licence v3.0 (credit line: \"Contains Parliamentary information licensed under the Open Parliament Licence v3.0\"). The OPL page itself returned HTTP 403 to curl; the Hansard pages carry \"© UK Parliament\" (raw/web/hansard_api_copyright.html)."
