def raw_region(files, paras):
    """For each raw file, find the line span covering the excerpt stretches found in it (normalized letters)."""
    def norm(t): return re.sub(r"[^a-z]", "", t.lower())
    pieces = []
    for p in paras:
        for part in re.split(r"…|\[[^\]]*\]", re.sub(r"\*+", "", p)):
            if len(norm(part)) >= 20: pieces.append(norm(part))
    spans, texts = [], []
    for f in files:
        lines = (RAW / f).read_text(encoding="utf-8", errors="ignore").split("\n")
        acc = ""; starts = []
        for l in lines:
            starts.append(len(acc)); acc += norm(l)
        hits = []
        for piece in pieces:
            for key in (piece[:40], piece[-40:]):
                j = acc.find(key)
                if j >= 0:
                    i = max(k for k in range(len(starts)) if starts[k] <= j); hits.append(i); break
        if not hits: continue
        lo, hi = min(hits), min(max(hits) + 3, min(hits) + 120)
        spans.append(f"{f} lines {lo + 1}-{hi}")
        texts.append(f"[{f}, lines {lo + 1}-{hi}]\n" + "\n".join(l.rstrip() for l in lines[lo:hi] if l.strip()))
    return "; ".join(spans), "\n\n".join(texts)

def used_as(sid):
    qs = [q["id"] for q in items if q["set"] == sid]
    tops = sorted({f"{q['topic']} (LO {q['lo']})" for q in items if q["set"] == sid}, key=lambda x: ([int(n) for n in x.split()[0].split(".")], x))
    kind = "exam" if sid.startswith("X") else "practice"
    return f"{kind} set {sid} ({qs[0]}–{qs[-1]})", ", ".join(tops)

import sys
ONLY = set(sys.argv[1:])  # optional: write only these keys, e.g. P1 P2
for key, md in M.items():
    if ONLY and key not in ONLY: continue
    sid, _, sub = key.partition(".")
    s = STIM[sid]
    paras = s["items"][int(sub) - 1]["paragraphs"] if sub else s["paragraphs"]
    lab = f" (Source {sub})" if sub else ""
    use, tops = used_as(sid)
    span, region = raw_region(RAWMAP[key], paras)
    out = [f"ID: {key}", f"Used as: {use}{lab}", f"Topic(s): {tops}", f"Work: {md['work']}", f"Edition / translation: {md['ed']}",
           f"URL curled: {md['url']}", f"Local raw copy: {md['raw']}", f"Locator: {md['loc']}", f"License basis: {md['lic']}", "",
           "EXCERPT AS PRINTED IN THE BANK:", ""] + [f"> {p}" for p in paras] + ["",
           f"RAW EXCERPT REGION ({span}; the bank's excerpt is cut from inside these lines):", "", region, "",
           "NOTES ON MISMATCHES, CUTS AND CORRECTIONS:", md["notes"], ""]
    (HERE / "sources" / f"{key}.md").write_text("\n".join(out), encoding="utf-8")
    print("wrote", key, span)
